#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> res;
    for (int i = n-y; i < n; i++) res.push_back(p[i]);
    for (int i = x; i < n-y; i++) res.push_back(p[i]);
    for (int i = 0; i < x; i++) res.push_back(p[i]);
    p = res;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    for (int placed = 0; placed < n; placed++) {
        // Find where element (placed+1) is
        int pos = -1;
        for (int i = placed; i < n; i++) {
            if (p[i] == placed + 1) { pos = i; break; }
        }
        if (pos == placed) continue; // already in place

        // Step 1: Move element from pos to position n-1 (last position)
        if (pos != n - 1) {
            // We want to move p[pos] to the end
            // Use x = pos+1, y = n-1-pos
            // This gives prefix=[0..pos], middle=[pos+1..pos], suffix=[pos+1..n-1]
            // Wait: middle = [x..n-y-1] = [pos+1 .. pos] which is empty when x+y=n
            // We need x+y < n, so middle must be non-empty
            // x = pos+1, y = n-1-pos, x+y = n, NOT valid
            // Use x = 1, y = n-1-pos (if pos > 0 and valid)
            // Actually: to get element at pos to end, use x=pos, y=n-1-pos if pos>0
            // x+y = n-1 < n. Valid if pos>0 and n-1-pos>0 (pos<n-1, true)
            if (pos > 0) {
                int x = pos, y = n - 1 - pos;
                if (x > 0 && y > 0 && x + y < n) {
                    ops.push_back({x, y});
                    apply_op(p, x, y);
                    // Element was at pos, now suffix=[pos+1..n-1] goes to front, prefix=[0..pos-1] goes to end
                    // Element at pos is first of middle, goes to position y = n-1-pos
                    // Actually let me just re-find it
                    for (int i = placed; i < n; i++) if (p[i] == placed+1) { pos = i; break; }
                }
            } else {
                // pos == 0: use x=1, y=1 to move things around (if n>3)
                int x = 1, y = 1;
                if (x + y < n) {
                    ops.push_back({x, y});
                    apply_op(p, x, y);
                    for (int i = placed; i < n; i++) if (p[i] == placed+1) { pos = i; break; }
                    if (pos != n-1 && pos > 0) {
                        x = pos; y = n-1-pos;
                        if (x > 0 && y > 0 && x+y < n) {
                            ops.push_back({x, y});
                            apply_op(p, x, y);
                            for (int i = placed; i < n; i++) if (p[i] == placed+1) { pos = i; break; }
                        }
                    }
                }
            }
        }

        // Step 2: Element should be at position n-1 (or already placed). Move to 'placed'.
        if (pos == placed) continue;
        // Move from pos=n-1 to placed: x=placed, y=1 if placed>0
        // suffix=[n-1], middle=[placed..n-2], prefix=[0..placed-1] -> [n-1][placed..n-2][0..placed-1]
        // Element goes to position 0... we want it at 'placed'
        // Use x = n-1-placed, y = 1: suffix=[n-1], middle=[n-1-placed..n-2], prefix=[0..n-2-placed]
        // Result: [n-1] [n-1-placed..n-2] [0..n-2-placed] -> element at position 0
        // Hmm. Let me try x=placed+1, y=n-1-placed if valid
        // No wait: element at n-1. x=placed, y=n-placed. x+y=n. Invalid.
        // x=placed+1, y=1: result = [p[n-1]] + [p[placed+1]..p[n-2]] + [p[0]..p[placed]]
        if (placed + 1 + 1 < n && pos == n-1) {
            ops.push_back({placed+1, 1});
            apply_op(p, placed+1, 1);
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x,y] : ops) printf("%d %d\n", x, y);
}
